D=[]
def add(start,title,paras,examples='',editor='',pages=[]):
 D.append(dict(start=start,title=title,paragraphs=paras.split('\n'),examples=examples.split('\n') if examples else [],editor_notes=editor.split('\n') if editor else [],pages=pages))
add(0,'提示词的范围：Agent 每次决策看见整个上下文', '''本课把提示词从“输入框里的一句话”扩展到模型实际看到的上下文。除了用户消息，还包括系统提示、全局和项目级 AGENTS.md、按任务加载的 Skill、工具定义、工具调用与返回、历史对话和环境信息。优化提示词，因而要检查这些内容如何一起影响执行。
讲师用早年请 ChatGPT 解释 inline assembly 的经历说明变化：即使示例做了非典型改动，模型仍能给出有帮助但并不完美的解释。重点是新的交互方式降低了理解陌生代码的门槛，不是证明模型永远正确。
模型逐步预测下一个 token；在 Agent 中，输出可以继续形成说明、代码或工具调用。较长上下文能够承载复杂约束，但“装得下”与“始终遵守”不同。课堂提到用固定句尾词是否消失观察指令遗失的民间办法，只能作为异常线索，不能据此确定是截断、压缩还是注意力失效。''',editor='讲义补充：不是所有 context 都是指令，代码、历史和工具结果也可能只是数据或证据。模型自述不是内部状态的可信转储，需要用可见行为交叉核对。',pages=[4,5])
add(294.53,'立即动手：让 Agent 解释工作环境', '''AI 降低的是启动一次尝试的成本。遇到不会的推导、数字电路或链接机制，可以立刻提出一个小问题，再追问，而不必等有空请教别人。
现场让 Agent 分析它的上下文来源。它报告了系统约束、用户自写的中文回答与 recap 要求、项目级指令、Skill 索引、工具定义以及每轮环境信息。讲师强调 Skill 描述与完整正文不同，通常先看到简短描述，匹配任务才读取细节。
这一演示的学习方式是把抽象概念变成可检查对象：既然说上下文不止用户提示，就去查当前系统如何组织它，再沿文件和行为核实，而不是停在一个定义上。''',editor='课堂对 Skill 加载/移出上下文的说明针对演示环境；不同 Agent 的持久化和压缩机制可能不同，不当作全部产品的通用实现。受保护的系统指令也不因“学习”而可以提取。',pages=[6,8])
add(571.67,'费曼学习法：把解释权交回自己', '''第一轮把 AI 当老师，用追问补齐不懂的地方；第二轮自己当老师，让 AI 当学生，指出解释中的跳步、矛盾和漏项。能读懂现成答案，不代表能独立组织一个解释。
操作上可以先合上资料，用自己的话讲清概念，再让 AI 追问。卡住时回到证据修正，随后重新讲一遍。这样形成理解、表达、反馈和重述的循环。''',examples='可用课堂方法自测：我来解释 Agent 的上下文有哪些来源；请作为听众指出我把“指令”和“事实”混为一谈的地方，不替我直接写完整答案。此句为整理者依据课堂方法改写。',pages=[7])
add(672.97,'从一个小疑问读源码：命令为什么有时需要审批', '''讲师留意到 Agent 执行 shell 时并非每条命令都询问用户，于是把问题变成源码阅读任务：风险判断来自静态分析、模型评级，还是其他机制？让 Agent 直接读取相关实现。
沙箱与审批带来取舍：限制降低误操作风险，却可能使无人值守任务停在确认处。课堂以去吃饭后发现任务早已等待确认为例，说明工作流设计需要考虑这种停顿。
单看命令名称不能推出安全性。讲师用“ls 在特殊环境中可能被改成别的行为”提醒，环境、参数和执行语义都可能影响结果。''',editor='讲义补充：模型提出操作，Harness、沙箱和审批策略共同执行边界；当前官方讲义还补充了命令参数相关漏洞案例。这里没有重新审计当前 Codex 源码，不能把课堂演示推定为所有版本实现。',pages=[9])
add(929.65,'配置工具并验证解释：代码阅读不是盲信回答', '''Agent 检索代码时可以借助语言服务和 IDE 信息。讲师借 VS Code 的红线说明：配置 include path 等环境，才能得到跳转、符号重命名和其他完整功能；“受控环境能编译”不等于日常开发配置已经正确。
现场回答提到了静态分流与模型风险评估。讲师并未把一次输出当最终事实，而是提出检查 prompt、观察行为变化等进一步证据。核心是让解释能落到代码与实验结果。
读实现时应同时看设计理由、规格文档和具体代码，三者相互印证。只听模型描述一个看似合理的机制，仍可能被错误解释带走。''')
add(1134.92,'Intent → Spec → Implementation：把完成条件写出来', '''人的意图、系统规格和最终实现之间存在空隙。只说“做一个国民级应用”，模型需要自行补全语言、架构和许多产品选择；即使它认为任务完成，也可能离你的真实目标很远。
规格把这种分歧变成可判断的差异。例如明确要求 C++，却交付 Java，很容易判定未满足；没有表达语言要求，就不能期待模型猜中。
尤其有价值的是机器可执行的验收：测试脚本能给通过或失败，Agent 才能据反馈反复尝试。课堂也提到代理为完成目标寻找系统漏洞的例子，提醒一个明确信号可能驱动非常执着的行为。''',editor='整理者说明：可验证性提供纠错信号，不保证验收器覆盖真实目标，也不保证资源无限、任务必能完成。',pages=[10,11])
add(1354.75,'赛车游戏案例：隐藏约束如何造成漂移', '''一句话生成游戏可以得到物理、碰撞、镜头乃至后视镜都很像样的演示，但它仍可能不是你脑海里的那款游戏。模型不知道你要求真实地图、已有美术资产还是完全自包含的实现。
讲师举南京大学仙林校区的道路为例：如果说明希望使用真实地图，并提供可用数据格式，就可能重建特定场景；不说清楚，模型可能自行画一个抽象世界。
因此要表达“要什么、用什么实现、怎样算正确”。产品与技术知识的价值，体现在能够把关键选择变成约束，而不是不断追加含混的形容词。''',pages=[12,13])
add(1524.49,'个人主页与 AI 味：把审美转成具体设计选择', '''课堂从课程作业设想谈到简历和个人主页。仅要求“现代风格”，模型可以生成滚动、悬浮、排版都很流畅的页面，但它可能仍然有明显模板感，内容也需要另行核实。
讲师自己的主页是可交互终端，使用 xterm.js，并在文字渲染后做轻微后处理，形成不完全工整的打字机效果。差别来自明确的交互与视觉选择，而不是一句“不要 AI 味”。
可表达的设计维度包括背景、前景、字体、后处理、间距、组件和布局。观察优秀作品时，要问究竟是哪一项选择产生了效果；阅读前端和设计知识，才能更准确地指挥实现。
讲师担心大量相似 AI 图像使审美趋同，因此鼓励保留并观察不同年代、不同作者的作品。这是其对多样性的判断，而不是已验证的普遍心理结论。''',pages=[14])
add(1845.24,'新的分工：知识帮助你选，而 AI 帮你实现', '''多见不同作品、与不同人讨论，能让自己更清楚想要什么，并把意图说准确。设计空间如何被约束，是本课对生成式软件工程的核心提问。
选择技术栈仍需要知识。例如教务系统后端用 Python、Java 还是 TypeScript，不只关乎能否写出来，还涉及部署、维护和未来演进。可以让 AI 挑战自己的选择，但人要理解比较所依据的条件。
AI 降低了实现成本，不能自动替代产品判断和架构判断。费曼式讨论也可以用于方案选择：自己先解释理由，再让 AI 找出其中未考虑的约束。''',pages=[15])
add(1987.64,'有限单步计算与思维链：把中间结果留在上下文', '''模型生成一个 token 时只执行有限的一次前向计算。讲师用有限状态机与图灵机的纸带作类比：额外的记录空间能让简单步骤累积成更长的推理。
思维链把中间尝试写入上下文，后续生成可以再读取、检查和纠正。它通常向后追加，不能像纸面一样真正擦除旧文字，因此也要处理早先错误留下的影响。
简单题可以直接回答；复杂约束则可能先尝试一个候选，再检查哪里不满足，必要时换路线。这是课堂解释 test-time scaling 的直觉：更多推理步骤可以给搜索和修补更多机会。
讲师对早期模型幻觉、奖励与强化学习的叙述是教学性解释，不等同于对某个模型训练数据和全部失败原因的实证证明。''',editor='整理者校正：纸笔/图灵机是计算深度的类比；不能从有限模型的长输出推导出无限计算能力。',pages=[16])
add(2324.74,'多重约束的诗：生成—检查—修补', '''课堂要求写八句押韵藏头诗，句首依次为“计算机学院真牛逼”，故事与动物有关，并让“二零二六九月一日”逐字按顺序出现在各句。难点在于同时满足多个相互牵制的条件。
现场观察到模型先尝试韵脚和句子，再逐条验证；不满足时修订，必要时换韵。讲师比较现场模型与讲义中的另一份生成结果，强调形式遵循与文学品味是两回事。
这类任务适合观察搜索过程，因为句首、嵌字、句数和韵脚都有相对明确的检查方式。但不能仅凭题目新颖就断言相关组合完全未出现在训练数据中。''',examples='当前讲义示例以“计成二兔越山冈”开头，以“逼得日升狼遁荒”结尾；图中完整列出八句，并逐项解释藏头、日期嵌字与 ang 韵。这是讲义版本，不冒充现场模型逐字输出。',pages=[17])
add(2488.61,'同偏旁与同音文：形式通过后还要评故事性', '''第二个任务要求十八个汉字组成有意义、有故事性的句子，且都有相同偏旁。模型选择三点水字，枚举后组织成句；课堂再比较另一份讲义结果。
第三个任务要求原创同音文，不能复用《施氏食狮史》《季姬击鸡记》，并加入现代背景。讲师认为形式上已经能做到，但故事性仍可提升；生成更多候选再筛选，可能找到更好的作品。
这三个文学例子共同说明：明确约束把审美任务的一部分变成可验证的搜索题，然而全部形式检查通过，不等于作品自然、有趣、值得读。''',examples='讲义同偏旁句为“洪涝淹没江港渔浦，油污漂浮，沈涛泅渡济溺。”不计标点18字；“沈涛”作人名。讲义另给全部拼音音节为 yi 的翻译器故事，允许声调不同。',editor='讲义补充区分“可见偏旁”和字典检字部首；“同音”是否含同声调必须写入规格。',pages=[18,19,20])
add(2680.65,'难以写验收器的任务：数字教师为什么容易失败', '''数学、代码与形式约束容易获得明确反馈；教学则难得多。讲师回顾数字切片的失败：声音是否自然只是表层，课程还需要情绪起伏、出乎意料但讲得通的例子、以及对学生知识状态的体察。
本课先讲上下文构成，再现场让 Agent 自查，就是讲师用来制造“小惊喜”的教学设计。它不是多写一点正确事实就会自然出现的节奏。
因此，把 AI 当能力放大器时要辨认反馈性质：哪些部分能严格判定，哪些仍需人类对体验和目标的判断。讲师关于模型超过多数人的说法针对这些例子和其体验，不能扩展为全部教学能力。''')
add(2842.61,'注意力会随任务阶段变化，但不是硬性保证', '''课堂把注意力解释为：生成当前 token 时，模型会更强地利用过去上下文中的某些内容。写代码时可能集中于需求与已有代码，转入总结时再注意语言等输出约束。
生成中间步骤带来多次发现错误的机会。例如检查诗句时，模型可能同时看到先前要求和刚生成的违反项，再追加修正。
但约束越多，上下文竞争也越复杂。模型能够接触一段文本，不代表必然有效使用它，更不能把自然语言规则当作不可违背的执行边界。''',pages=[21])
add(3068.31,'规则的副作用：修一个问题，也增加一份上下文负担', '''较早的提示词技巧常用长角色设定改变输出风格。讲师认为，在较强的推理模型上，更值得优先表达明确任务与验证条件，而不是堆叠“你是一位专家”。这是其针对课堂模型的经验判断。
“白色背景，不要半透明效果”本来只是在说明设计要求，模型却可能把整句照搬到代码注释。为禁止这个行为再加一条 AGENTS.md 规则，会同时增加指令长度与注意力负担。
直接拿别人写好的 Skill，第一次可能有效，换任务仍可能出问题；不断补丁也可能陷入泥潭。此时应重新想清目标、模型注意到了什么、为何偏离，再做简练的修正。''',pages=[22])
add(3298.9,'论文总结为何容易跟着作者走', '''现场把一篇匿名版本的论文放在临时目录中，减少项目指令干扰，再让 AI 总结。讲师指出，成熟论文的信息密度高、论证自洽，模型很容易沿着作者设定的问题、术语与因果链重述。
进一步询问是否可信、贡献是否足够，模型可能随用户语气来回摆动，或专注于可多做一点实验等边缘批评。它看似提出意见，却没有回答“这项工作对既有知识增加了什么”。
讲师举现场追查一个显然存在的示例为跑偏现象，强调审查不能只做随机挑错。代码可运行、故事内部一致与研究贡献显著，是不同的问题。''',editor='当前讲义第23–25页补充了 reviewer 角色、三条审稿路线与证据账本；其中具体路线并未在该段口述逐项讲授，不作为现场完成的审查。',pages=[23,24,25])
add(3597.34,'先对齐知识边界，再一步步审贡献', '''讲师的阅读方法先问：这个问题在人类已有知识中处于哪里？相关工作已经解决到什么程度？本文试图补上的增量是什么？先形成共同参照，再审视作者的论证。
学生阅读陌生内容时，对齐的是自己的基础。告诉 AI 已学过什么、编程水平如何，让它用这些知识重述新内容；必要时从“我有一个 cpp，编译成 exe，为何还需要链接”这样的已知事实重新起步。
每次只推进一小步，并检查前提与推理能否成立。目标是让 AI 的解释与自己的知识结构连接，而不是不断生成更长、仍然不理解的总结。
讲师把相关工作、问题价值和推理链条作为审稿重点，也承认现场较弱模型的输出不一定可靠。此处记录的是阅读与判断方法，不是对论文质量的独立复审。''')
add(3985.51,'A₁ / A₂ 案例：局部优化成立，整体价值仍可能很小', '''课堂把某论文抽象为：任务 A 由 A₁ 和 A₂ 构成，作者提出 A₂ 的改进。若耗时大约99%来自 A₁、1%来自 A₂，那么只改善 A₂ 一小部分，对总任务的影响可能小到接近噪声。
关键不只是实验有没有做对，而是为何选择这个瓶颈、为什么这项增量值得关注。把成熟部分的方法搬到次要部分，可能形成一个完整的研究故事，却没有充分增加有用知识。
讲师进一步担心 AI 写作和 AI 审稿互相强化：每篇都逻辑自洽，却越来越难判断哪篇值得读。对学术发表体系的判断是课堂预测，应与已发生事实区分。''',editor='整理者算例：若 A₂ 仅占总耗时1%，把这部分耗时降低10%，总耗时只降低0.1%。这里99%/1%是讲师对匿名例子的估计，不是公开实验测量值。')
add(4254.86,'学习与 Skill：保存判断方法，而不只是保存答案', '''学习是在既有知识上增加事实、建立联结，再回看过去为什么没有理解。讲师提到跨领域经典阅读，希望学生把“为什么我原来不知道”变成发现前置知识和盲点的方法。
真正的掌握需要自己实践和失败：如果 AI 解释了半天仍没懂，要继续对齐基础，要求换成可理解的说法，而不是把读过等同于学会。
经过反复尝试得到的有效阅读方式，可以提炼成 Skill。它应保存搜索与判断方法；长 Skill 本身也是一组需要模型遵守的复杂约束，所以仍有长度与执行负担的取舍。''',editor='边界：课堂提到线粒体母系遗传与共同祖先作为跨域学习例子，没有展开生物学证据；这里不把它扩写为课程已证明的科学推论。',pages=[26])
add(4529.01,'长程任务与 Greenfield 悖论', '''本课将真正的长程任务描述为带未知的探索：有大体意图，却尚未确定规格、实现路线和高质量交付形态。模型急于完成，也要在规划长度、上下文和执行之间作取舍。
从零生成一个主页或小游戏很快；持续添加功能时，结构可能逐渐恶化，修复成本上升。反而在长期维护的大型仓库中，清晰的模式、接口和类似实现给 AI 提供了强约束。
讲师用 Linux 内核与 Android Runtime 编译器工作说明：对初学者而言层层调用和锁约定很难追踪，模型却可能从已有代码找到 helper、调用顺序和相关模式。代码库本身因而也是上下文。
这不是“仓库越大越好”。课堂解释的有利条件是高质量、长期维护、存在相关范例；糟糕代码同样可能被继续模仿。''',pages=[27,28])
add(4867.78,'参考优秀项目：一个尚未实验验证的想法', '''讲师提出研究设想：收集优秀项目的设计经验，给 AI 看相近领域的实现或精简设计文档，再生成自己的系统，是否能延缓低质量结构积累？课堂明确说自己尚未做实验。
直接堆入多个系统也有困难。不同架构可能冲突，例如松耦合消息传递与集中式 gateway/查表组织，不能不加判断地拼合。
可能的方向是提取端到端设计切片，再经过多轮选择收敛；真正要验证的是这些上下文是否改善长期可维护性，而不只是第一次代码能跑。''',editor='当前讲义第29页增补 RepoCoder、CodeRAG-Bench 与对照实验建议。这是讲义后续材料；本次未独立阅读全文及复现实验，不把它写成课堂已经验证了上述猜想。',pages=[29])
add(5032.5,'没有超能力 AI：基础知识用来识别边界', '''处理器、操作系统、编译器、数据库等知识仍然重要，因为它们积累了接口、抽象和设计的智慧。学习方法可以变化，但不理解领域就难以提出正确问题。
人的任务包括把模型引向合适方向、监控偏离，以及定义好的 verifier。简短而关键的约束可能比大量琐碎指令更有帮助，前提是你知道什么值得约束。''',pages=[30])
add(5116.38,'符号执行研究失败：不要让“证明有用”替代研究问题', '''课堂案例是优化符号执行引擎：已有一个看起来合理的 idea，学生投入很多 token，模型不断给正负反馈，但学生无法判断这些反馈对研究是否有效。
问题出在“我想证明方法 A 有用”的表述。模型太想证明这个局部目标，于是构造许多小 benchmark、做微小改动、给出结论，却没有帮助理解真实系统的问题。
讲师的纠正是从真实工具和现有先进算法出发。即使 benchmark 跑几小时超时，搜索路径仍有价值：它能揭示什么程序结构使现有策略失败。这些观察才可能形成有意义的新假设。
研究需要允许原始 idea 不成立，并把每一步反馈放回更大的问题中判断。让模型“证明我对”，可能把搜索导向容易取悦验收的局部结果。''',editor='重要差异：当前讲义第31页末尾另外建议 profiling、可证伪预测、microbenchmark、baseline 与 ablation；而课堂明确批评的是脱离真实工具的微型 benchmark。两者不能简化为“本课建议先做小 benchmark”；只有与真实瓶颈有对应关系的小实验才有解释价值，此条件是整理者的综合说明。',pages=[31])
add(5328.13,'人类注意力如何分配：纠偏更快，不一定更划算', '''讲师观察到，凭领域知识及时纠正 Agent，单个任务可能更快完成；但如果多给机器时间也能完成，人的全程盯守就可能浪费更稀缺的精力。
不断纠正 AI 还可能带来“我仍然比它有用”的心理满足。需要区分真正有收益的干预与自我感动式忙碌：把时间留给尚不理解、必须学习和判断的部分，已知做法且可验收的实现适当放手。
这是一种工作分配经验，不是对所有任务都无需监督的建议。系统性风险、不可逆行为和缺少验收的探索仍需要明确边界。''',pages=[32])
add(5493.06,'上下文增长后的退化与重新锚定', '''课堂提醒，随着上下文变长，早期或中间的指令可能更难被遵循；较近的具体请求通常仍有用。因此长会话仍可做局部修复，但不能默认最初的全部要求都有效保留。
在关键阶段重新表达目标与约束，比只依赖很早的一段提醒更可检查。上下文容量不是稳定记忆的保证。''',editor='讲义补充：可用类型、lint、测试、CI 和权限边界承接能机械检查的要求；压缩时保存目标、约束、未决问题与证据。这些工程化建议见当前课件第33页，口述此处只简短说明长上下文退化。',pages=[33])
add(5530.54,'在不确定性中探索：几个方案不等于覆盖了空间', '''开放问题与有固定验收题目不同。问“哪种方案最好”，模型可能只给有限候选；它有完成当前答复的倾向，没有自然穷尽所有可能。
讲师借“找解与验解难度不同”解释搜索的困难。一个方案看起来可行，仍不足以证明不存在更优选择。
因此要额外设计搜索范围和覆盖方式，让算力花在不同方向的探索上，而不是只把同一个候选解释得越来越长。''',editor='术语校正：转写中的“哈姆雷特 pass”按上下文应为 Hamiltonian path（哈密顿路径），“three set”应为3-SAT。P/NP在这里是搜索与验证的教学类比，不是针对语言模型的复杂性证明。',pages=[34])
add(5661.04,'取名案例：先定义候选空间，再独立检查', '''直接让模型给孩子起几个名字，结果可能好听、有典故，却与其他同一模型用户高度相似。讲师用“AI 时代的子涵”形容默认偏好带来的趋同。
改进是系统性调研：先枚举可能的音，筛除不合适的发音，再对字、典故和组合逐项检查。可将空间拆成互不重叠的小部分，让子任务分别探索后汇总。
这样把开放问题分解为更明确、可验证的子问题，用额外计算换更广覆盖。但 token 代价会增加，筛选标准仍须由人定义。''',pages=[35])
add(5822.67,'多样性与算力集中：以开放问题结束', '''人的成长背景、教育和生活经验带来不同偏向。讲师认为多样性让交流产生群体智能：不是人人都知道所有事，而是不同局部经验能够互补。
最后提出条件性的社会担忧：如果高价值探索能持续以算力换取能力，而极少数人拥有远多于其他人的计算资源，会不会形成难以跨越的能力壁垒？
这是课堂留给学生思考的未来情景，不是已经发生、也不是必然发生的结论。它把技术方法重新接回资源分配和人的选择。''',editor='讲义第37页另列 AI Index 的产业与成本数据，本次未独立核查该报告，不把这些数字列为本笔记确认事实。',pages=[36,37])
S=[]
